```yaml
spec:
  podSelector: {}
  policyTypes:
  - Egress
```

Desired structure:
```yaml
spec:
  podSelector: {}
  policyTypes:
  - Egress
  egress:
    - to:
      - selector:
          matchLabels:
            app: dep
      ports:
      - protocol: TCP
        port: 80
    - ports:
      - protocol: UDP
        port: 53
      to:
      - namespaceSelector: {} # Broad DNS access
    - ports:
      - protocol: TCP
        port: 53
      to:
      - namespaceSelector: {} # Broad DNS access
```

