    }
  ]
}
```

Rule 3 (DNS TCP):
```json
{
  "to": [
    {
      "namespaceSelector": {}
    }
  ],
  "ports": [
    {
      "protocol": "TCP",
      "port": 53
    }
  ]
}
```
